def prod_int_partII(n, s):
    if n <= 1:
        return [0, 0, []]
    def factorize(x):
        factors = []
        i = 2
        while i * i <= x:
            if x % i:
                i += 1
            else:
                x //= i
                factors.append(i)
        if x > 1:
            factors.append(x)
        return factors

    def dfs(product, factors):
        if len(factors) == s:
            total_products.add(product)
        elif len(factors) < s:
            for i, f in enumerate(factors):
                new_product = product * f
                new_factors = factors[i+1:]
                dfs(new_product, new_factors)

    total_products = set()
    dfs(1, factorize(n))
    total_amount = len(total_products)
    count_s = sum(1 for p in total_products if len(factorize(p)) == s)
    result = [total_amount, count_s]
    if count_s > 0:
        result.append(sorted([sorted(factors) for factors in total_products if len(factors) == s]))
