def interpreter(code, tape):
    tape = list(tape)
    ptr = 0
    pc = 0
    while pc < len(code):
        cmd = code[pc]
        if cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == '*':
            tape[ptr] = '1' if tape[ptr] == '0' else '0'
        elif cmd == '[':
            if tape[ptr] == '0':
                depth = 1
                while depth > 0:
                    pc += 1
                    if code[pc] == '[':
                        depth += 1
                    elif code[pc] == ']':
                        depth -= 1
        elif cmd == ']':
            if tape[ptr] != '0':
                depth = 1
                while depth > 0:
                    pc -= 1
                    if code[pc] == '[':
                        depth -= 1
                    elif code[pc] == ']':
                        depth += 1
        pc += 1
        ptr %= len(tape)
    return ''.join(tape)

def largest_divisible_subset(nums):
    if not nums:
        return []
    nums.sort()
    dp = [[num] for num in nums]
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[i]) < len(dp[j]) + 1:
                dp[i] = dp[j] + [nums[i]]
